VALUES ('telc-deutsch-b1.sb1.grammar-wortstellung-v1','v1','telc-deutsch-b1','SB1','SB',1,'Grammatikübung: Wortstellung im Nebensatz','{"practice_kind":"grammar-drill","instruction":"Ergänze die Sätze. Dies sind einzelne Grammatikübungen, kein telc-Prüfungssatz.","letter":"1. Ich weiß, dass er morgen nach Berlin ___ .\n2. Sie kommt heute nicht, weil sie ___ .\n3. Ich rufe dich an, wenn ich ___ .\n4. Er sagt, dass er das Buch schon ___ .\n5. Ich habe gehört, dass du ___ .\n6. Obwohl es stark ___ , sind wir spazieren gegangen.\n7. Ich bleibe zu Hause, weil ich sehr ___ .\n8. Weißt du, wann der Zug ___ ?\n9. Ich möchte wissen, ob du ___ .\n10. Sie hat gesagt, dass sie uns später ___ .\n11. Ich habe ihn gefragt, wo er ___ .\n12. Es ist wichtig, dass du pünktlich ___ .","gaps":[{"n":"g_wortstellung_nebensatz_1bwzwum","prompt":"Ich weiß, dass er morgen nach Berlin ___ .","options":{"a":"fährt","b":"er fährt","c":"fahren"}},{"n":"g_wortstellung_nebensatz_1bns8w","prompt":"Sie kommt heute nicht, weil sie ___ .","options":{"a":"ist krank","b":"krank sein","c":"krank ist"}},{"n":"g_wortstellung_nebensatz_e9k8r3","prompt":"Ich rufe dich an, wenn ich ___ .","options":{"a":"Zeit haben","b":"Zeit habe","c":"habe Zeit"}},{"n":"g_wortstellung_nebensatz_ioh2c5","prompt":"Er sagt, dass er das Buch schon ___ .","options":{"a":"gelesen hat","b":"hat gelesen","c":"gelesen haben"}},{"n":"g_wortstellung_nebensatz_otwf6u","prompt":"Ich habe gehört, dass du ___ .","options":{"a":"bist umgezogen","b":"umgezogen sein","c":"umgezogen bist"}},{"n":"g_wortstellung_nebensatz_1r4f1ml","prompt":"Obwohl es stark ___ , sind wir spazieren gegangen.","options":{"a":"regnen hat","b":"geregnet hat","c":"hat geregnet"}},{"n":"g_wortstellung_nebensatz_ivslwl","prompt":"Ich bleibe zu Hause, weil ich sehr ___ .","options":{"a":"müde bin","b":"bin müde","c":"müde sein"}},{"n":"g_wortstellung_nebensatz_wn4ry5","prompt":"Weißt du, wann der Zug ___ ?","options":{"a":"fährt ab","b":"abfahren","c":"abfährt"}},{"n":"g_wortstellung_nebensatz_i65oho","prompt":"Ich möchte wissen, ob du ___ .","options":{"a":"mitkommen","b":"mitkommst","c":"kommst mit"}},{"n":"g_wortstellung_nebensatz_1tp4oj","prompt":"Sie hat gesagt, dass sie uns später ___ .","options":{"a":"anruft","b":"ruft an","c":"anrufen"}},{"n":"g_wortstellung_nebensatz_1xmbg3q","prompt":"Ich habe ihn gefragt, wo er ___ .","options":{"a":"wohnt er","b":"wohnen","c":"wohnt"}},{"n":"g_wortstellung_nebensatz_1649nxw","prompt":"Es ist wichtig, dass du pünktlich ___ .","options":{"a":"kommen","b":"kommst","c":"kommst du"}}]}'::jsonb,12,false,'telc-deutsch-b1.sb1.grammar-wortstellung-v1@v1');
