VALUES ('telc-deutsch-b1.sb1.grammar-wortstellung-v1','v1','{"g_wortstellung_nebensatz_1bwzwum":"a","g_wortstellung_nebensatz_1bns8w":"c","g_wortstellung_nebensatz_e9k8r3":"b","g_wortstellung_nebensatz_ioh2c5":"a","g_wortstellung_nebensatz_otwf6u":"c","g_wortstellung_nebensatz_1r4f1ml":"b","g_wortstellung_nebensatz_ivslwl":"a","g_wortstellung_nebensatz_wn4ry5":"c","g_wortstellung_nebensatz_i65oho":"b","g_wortstellung_nebensatz_1tp4oj":"a","g_wortstellung_nebensatz_1xmbg3q":"c","g_wortstellung_nebensatz_1649nxw":"b"}'::jsonb,'{"g_wortstellung_nebensatz_1bwzwum":"Im Nebensatz steht das konjugierte Verb am Ende: … dass er morgen nach Berlin fährt.","g_wortstellung_nebensatz_1bns8w":"Nach \"weil\" steht das Verb am Satzende.","g_wortstellung_nebensatz_e9k8r3":"Nebensatz mit \"wenn\" → Verb am Ende.","g_wortstellung_nebensatz_ioh2c5":"Im Nebensatz steht das Hilfsverb nach dem Partizip am Ende.","g_wortstellung_nebensatz_otwf6u":"Perfekt im Nebensatz: Partizip + Hilfsverb am Ende.","g_wortstellung_nebensatz_1r4f1ml":"Nach \"obwohl\" steht das Verb am Ende.","g_wortstellung_nebensatz_ivslwl":"Verb am Ende im \"weil\"-Satz.","g_wortstellung_nebensatz_wn4ry5":"Indirekte Frage: trennbares Verb bleibt zusammen am Ende.","g_wortstellung_nebensatz_i65oho":"Nach \"ob\" steht das Verb am Ende – trennbares Verb zusammen.","g_wortstellung_nebensatz_1tp4oj":"Im Nebensatz bleibt das trennbare Verb am Ende zusammen.","g_wortstellung_nebensatz_1xmbg3q":"Indirekte Frage: Verb am Ende.","g_wortstellung_nebensatz_1649nxw":"\"dass\"-Satz → konjugiertes Verb am Ende."}'::jsonb,NULL);
